import {
  CanActivate,
  ExecutionContext,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { UserRoles } from './roles.enum'; // Assuming you have an enum for user roles

@Injectable()
export class AuthGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredPermissions = this.reflector.getAllAndOverride<string[]>(
      'permissions',
      [context.getHandler(), context.getClass()],
    );

    if (!requiredPermissions || !Array.isArray(requiredPermissions)) return true;

    const req = context.switchToHttp().getRequest();
    const currentUser = req.user; // Assuming you have a method to get the current user

    if (currentUser && Array.isArray(currentUser.permissions)) {
      const hasPermission = requiredPermissions.some(permission =>
        currentUser.permissions.includes(permission),
      );
      if (!hasPermission) throw new UnauthorizedException('Unauthorized');
      return true;
    }

    throw new InternalServerErrorException(
      `User does not have required permissions`,
    );
  }
}

// roles.enum.ts
export enum UserRoles {
  ADMIN = 'admin',
  USER = 'user',
}
